func (r *Regexp) UnmarshalJSON(b []byte) error {
	var s *string
	if err := json.Unmarshal(b, &s); err != nil {
		return fmt.Errorf("regexp must be a JSON string or null: %w", err)
	}

	if s == nil || *s == "" {
		r.Regexp = nil
		return nil
	}

	rr, err := regexp.Compile(*s)
	if err != nil {
		return fmt.Errorf("invalid regexp %q: %w", *s, err)
	}
	r.Regexp = rr
	return nil
}
